"""Semantic mathematics and source-backed course content."""

def frac(n, d):
    return f'<span class="math-frac"><span class="math-num">{n}</span><span class="math-den">{d}</span></span>'

def vec(x): return f'<b>{x}</b>'
def sub(x, s): return f'{x}<sub>{s}</sub>'
def unit(s): return sub(vec('a'), s)
def scalar(x): return f'<em>{x}</em>'
def deriv(x, y): return frac('∂' + x, '∂' + y)
def math(x): return f'<div class="math-display">{x}</div>'
def det(symbol='H'):
    spatial = symbol.endswith('s')
    name = symbol[:-1] if spatial else symbol
    rows = [[unit(i) for i in 'xyz'], [deriv('',i) for i in 'xyz'], [sub(scalar(name),i+('s' if spatial else '')) for i in 'xyz']]
    return '∇ × ' + (sub(vec(name),'s') if spatial else vec(name)) + ' = <span class="math-det"><table class="math-table">' + ''.join('<tr>' + ''.join('<td>'+v+'</td>' for v in row)+'</tr>' for row in rows) + '</table></span>'

E,H,D,B,J,V,I,Q = [vec(x) if x in 'EHDBJ' else scalar(x) for x in ['E','H','D','B','J','V','I','Q']]
rv,rs,eps0,mu0 = 'ρ<sub>v</sub>','ρ<sub>s</sub>','ε<sub>0</sub>','μ<sub>0</sub>'
divcart = ' + '.join(deriv(sub(scalar('A'),i),i) for i in 'xyz')
divcyl = frac('1','ρ')+deriv('(ρ'+sub(scalar('A'),'ρ')+')','ρ')+' + '+frac('1','ρ')+deriv(sub(scalar('A'),'ϕ'),'ϕ')+' + '+deriv(sub(scalar('A'),'z'),'z')
divsph = frac('1','r<sup>2</sup>')+deriv('(r<sup>2</sup>'+sub(scalar('A'),'r')+')','r')+' + '+frac('1','r sin θ')+deriv('('+sub(scalar('A'),'θ')+' sin θ)','θ')+' + '+frac('1','r sin θ')+deriv(sub(scalar('A'),'ϕ'),'ϕ')
gradcart = ' + '.join(deriv(V,i)+unit(i) for i in 'xyz')
gradcyl = deriv(V,'ρ')+unit('ρ')+' + '+frac('1','ρ')+deriv(V,'ϕ')+unit('ϕ')+' + '+deriv(V,'z')+unit('z')
gradsph = deriv(V,'r')+unit('r')+' + '+frac('1','r')+deriv(V,'θ')+unit('θ')+' + '+frac('1','r sin θ')+deriv(V,'ϕ')+unit('ϕ')
lapcart = ' + '.join(frac('∂<sup>2</sup>'+V,'∂'+i+'<sup>2</sup>') for i in 'xyz')
lapcyl = frac('1','ρ')+deriv('('+ 'ρ'+deriv(V,'ρ')+')','ρ')+' + '+frac('1','ρ<sup>2</sup>')+frac('∂<sup>2</sup>'+V,'∂ϕ<sup>2</sup>')+' + '+frac('∂<sup>2</sup>'+V,'∂z<sup>2</sup>')
lapsph = frac('1','r<sup>2</sup>')+deriv('(r<sup>2</sup>'+deriv(V,'r')+')','r')+' + '+frac('1','r<sup>2</sup> sin θ')+deriv('(sin θ'+deriv(V,'θ')+')','θ')+' + '+frac('1','r<sup>2</sup> sin<sup>2</sup> θ')+frac('∂<sup>2</sup>'+V,'∂ϕ<sup>2</sup>')
curlcart = ' + '.join('('+deriv(sub(scalar('H'),a),b)+' − '+deriv(sub(scalar('H'),b),a)+')'+unit(c) for a,b,c in [('z','y','x'),('x','z','y'),('y','x','z')])
curlcyl = '('+frac('1','ρ')+deriv(sub(scalar('H'),'z'),'ϕ')+' − '+deriv(sub(scalar('H'),'ϕ'),'z')+')'+unit('ρ')+' + ('+deriv(sub(scalar('H'),'ρ'),'z')+' − '+deriv(sub(scalar('H'),'z'),'ρ')+')'+unit('ϕ')+' + '+frac('1','ρ')+'('+deriv('(ρ'+sub(scalar('H'),'ϕ')+')','ρ')+' − '+deriv(sub(scalar('H'),'ρ'),'ϕ')+')'+unit('z')
curlsph = frac('1','r sin θ')+'('+deriv('('+sub(scalar('H'),'ϕ')+' sin θ)','θ')+' − '+deriv(sub(scalar('H'),'θ'),'ϕ')+')'+unit('r')+' + '+frac('1','r')+'('+frac('1','sin θ')+deriv(sub(scalar('H'),'r'),'ϕ')+' − '+deriv('(r'+sub(scalar('H'),'ϕ')+')','r')+')'+unit('θ')+' + '+frac('1','r')+'('+deriv('(r'+sub(scalar('H'),'θ')+')','r')+' − '+deriv(sub(scalar('H'),'r'),'θ')+')'+unit('ϕ')
continuity = '∇ • '+J+' = −'+deriv(rv,'t')
faraday = '∇ × '+E+' = −'+deriv(B,'t')
ampere = '∇ × '+H+' = '+J+' + '+deriv(D,'t')
stokes = '∮<sub>C</sub> '+H+' • d<b>l</b> = ∫<sub>S</sub> (∇ × '+H+') • d<b>s</b>'
maxpoint = '∇ • '+D+' = '+rv+'<br>'+ampere+'<br>'+faraday+'<br>∇ • '+B+' = 0'
maxint = '∯<sub>S</sub> '+D+' • d<b>s</b> = ∫<sub>vol</sub> '+rv+' dv<br>∮<sub>C</sub> '+H+' • d<b>l</b> = ∫<sub>S</sub> '+J+' • d<b>s</b> + '+deriv('','t')+'∫<sub>S</sub> '+D+' • d<b>s</b><br>∮<sub>C</sub> '+E+' • d<b>l</b> = −'+deriv('','t')+'∫<sub>S</sub> '+B+' • d<b>s</b><br>∯<sub>S</sub> '+B+' • d<b>s</b> = 0'
phasor = '∇ × '+sub(E,'s')+' = −jω'+sub(B,'s')+'<br>∇ × '+sub(H,'s')+' = '+sub(J,'s')+' + jω'+sub(D,'s')
electricbc = '<em>E</em><sub>t1</sub> = <em>E</em><sub>t2</sub><br><em>D</em><sub>n1</sub> − <em>D</em><sub>n2</sub> = '+rs
magbc = '<em>B</em><sub>n1</sub> = <em>B</em><sub>n2</sub><br>'+unit('n12')+' × ('+sub(H,'1')+' − '+sub(H,'2')+') = <b>K</b>'
wire = H+' = '+frac(I,'2πρ')+unit('ϕ')
biot = 'd'+H+' = '+frac(I+' d<b>l</b>′ × '+unit('R'),'4πR<sup>2</sup>')

